def f(g):
    g=[row[:] for row in g]
    from collections import deque
    bg=max(set(x for r in g for x in r), key=[x for r in g for x in r].count)
    seen=set(); os_=[]
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c]!=0 and g[r][c]!=bg and (r,c) not in seen:
                col=g[r][c]; q=deque([(r,c)]); seen.add((r,c)); cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<len(g) and 0<=nx<len(g[0]) and g[ny][nx]==col and (ny,nx) not in seen:
                            seen.add((ny,nx)); q.append((ny,nx))
                ys=[y for y,x in cells]; xs=[x for y,x in cells]
                shape=tuple(''.join('#' if (min(ys)+i,min(xs)+j) in cells else '.' for j in range(max(xs)-min(xs)+1)) for i in range(max(ys)-min(ys)+1))
                os_.append((min(ys),min(xs),col,cells,shape))
    from collections import defaultdict
    by=defaultdict(list)
    for o in os_: by[o[4]].append(o)
    for shp,lst in by.items():
